/*
 * Convenience lookup retained for Website Management.
 */
window.RUKHNAV_THEME_PRESETS.get =
    function getThemePreset(id) {
        return (
            window.RUKHNAV_THEME_PRESETS.find(
                preset => preset.id === id
            ) || null
        );
    };
